/* ============================================================
   BANCO CURADO — fútbol, delantero, rehab de recto femoral
   Campos: id, n (nombre), pat (patrón), c (contracción),
   pl (plano), lat (U/B), fv (zona fuerza-velocidad), k (costo 1-5),
   z (zonas), s (slots que puede cubrir), f (fase mínima con lesión
   de RF activa), eq (equipo), m (músculos), cue (indicación),
   img (id de imagen en la biblioteca extendida), x (extra: why/prog/reg)
   ============================================================ */
function X(id, n, pat, c, pl, lat, fv, k, z, s, f, eq, m, cue, img, x) {
  return Object.assign({ id, n, pat, c, pl, lat, fv, k, z: z.split(' '), s: s.split(' '), f, eq: eq.split(','), m, cue, img: img || null }, x || {});
}

